mapper.select:
SELECT TC.COMPANY_ID, TC.COMPANY_NM, TC.COMPANY_TYPE, TC.CEO_NM, TC.USE_YN, TO_CHAR(TC.REG_DT, 'YYYYMMDD') AS REG_DT, TC.BRANCH_ID FROM TM_COMPANY TC WHERE 1=1
AND TC.COMPANY_ID = #{COMPANY_ID}
AND TC.COMPANY_NM LIKE '%' || #{COMPANY_NM} || '%'
AND TC.COMPANY_TYPE = #{COMPANY_TYPE}
AND TC.USE_YN = #{USE_YN}
ORDER BY TC.COMPANY_ID

SELECT ND.DELIVERY_ID, ND.DELIVERY_NM, ND.COMPANY_ID, TC.COMPANY_NM, ND.TEL_NO, ND.USE_YN FROM TM_NUMPLATE_DELIVERY ND, TM_COMPANY TC WHERE ND.COMPANY_ID = TC.COMPANY_ID(+)
AND ND.COMPANY_ID = #{COMPANY_ID}
ORDER BY ND.DELIVERY_ID

SELECT COMPANY_ID, COMPANY_NM, BRANCH_ID, BRANCH_NM, BIZ_NO, POST_NO, PASS_WD, TEL_NO, PKG_COMMON.FN_DECRYPT(PHONE_NO) AS PHONE_NO, PKG_COMMON.FN_DECRYPT(ADDRESS) AS ADDRESS, PKG_COMMON.FN_DECRYPT(ADDRESS_DT) AS ADDRESS_DT, ETC1, ETC2, ETC3, ETC4, ETC5, COMPANY_ID || BRANCH_ID as CODE_ID, BRANCH_NM as CODE_NM, USE_YN FROM TM_CARNO_COMPANY WHERE USE_YN = 'Y'
AND COMPANY_ID = #{COMPANY_ID}
AND BRANCH_ID = #{BRANCH_ID}
AND (PKG_COMMON.FN_DECRYPT(ADDRESS) LIKE '%' || #{AREA} || '%' OR BRANCH_NM LIKE '%' || #{AREA} || '%')
ORDER BY COMPANY_ID, TO_NUMBER(BRANCH_ID)

SELECT CONFIG_SEQ, COMPANY_ID, WORK_CD, DATASET, FIELD_ID, RULE_TYPE, RULE_VALUE,
       COND_FIELD, COND_VALUE, ORDER_NO, USE_YN, REMARK
FROM TM_COMPANY_CONFIG
WHERE USE_YN = 'Y'
  AND (
        COMPANY_ID = 'ALL'

            OR COMPANY_ID = #{COMPANY_ID}

      )
  AND WORK_CD = #{WORK_CD}
ORDER BY COMPANY_ID ASC, ORDER_NO ASC, CONFIG_SEQ ASC

SELECT COUNT(1)
FROM TM_SANGSA
WHERE COMPANY_ID = #{COMPANY_ID}
  AND BRANCH_ID = #{BRANCH_ID}
  AND UPPER(TRIM(SANGSA_NM)) = UPPER(TRIM(#{SANGSA_NM}))
  AND NVL(USE_YN, 'Y') = 'Y'

SELECT TO_CHAR(
           NVL(MAX(
               CASE
                   WHEN REGEXP_LIKE(TO_CHAR(SANGSA_ID), '^[0-9]+$')
                   THEN TO_NUMBER(SANGSA_ID)
                   ELSE 0
               END
           ), 0) + 1
       ) AS NEXT_SANGSA_ID
FROM TM_SANGSA
WHERE COMPANY_ID = #{COMPANY_ID}
  AND BRANCH_ID = #{BRANCH_ID}
